beforeExample:
package test;

import org.eclipse.jface.text.Assert;

public class MyClass {
    public void foo(boolean condition, String msg) {
        Assert.isTrue(condition, msg);
    }
}

afterExample:
package test;

import org.eclipse.core.runtime.Assert;

public class MyClass {
    public void foo(boolean condition, String msg) {
        Assert.isTrue(condition, msg);
    }
}

negativeExample:
package test;

import org.eclipse.core.runtime.Assert;

public class MyClass {
    public void foo(boolean condition, String msg) {
        // Already using org.eclipse.core.runtime.Assert, should not match
        Assert.isTrue(condition, msg);
    }
}
